use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm::{self, Reply};

struct Node;

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        let system = "You are a customer support agent. Answer the user's \
            question using the provided knowledge. You may call the `lookup` \
            tool to retrieve additional knowledge from the knowledge base. \
            When you have enough information, reply with the final answer text.";

        let mut prompt = build_prompt(&ctx);

        // Bounded tool-orchestration loop. The only tool this node can invoke
        // is `lookup`, because the only tool interface in its world is kb-read.
        let mut rounds: u32 = 0;
        loop {
            match tool_llm::generate(system, &prompt) {
                Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                Reply::Call(req) => {
                    rounds += 1;
                    if rounds > 8 {
                        return ResponseResult::Error(LlmError {
                            message: "tool-call limit exceeded".to_string(),
                        });
                    }
                    if req.tool == "lookup" {
                        let results = kb_read::lookup(&req.query);
                        prompt.push_str("\n\n[lookup results for \"");
                        prompt.push_str(&req.query);
                        prompt.push_str("\"]\n");
                        if results.is_empty() {
                            prompt.push_str("(no results)\n");
                        } else {
                            for r in &results {
                                prompt.push_str("- ");
                                prompt.push_str(r);
                                prompt.push('\n');
                            }
                        }
                    } else {
                        // Any other tool is out of scope for this node; report
                        // it back to the model so it can answer without it.
                        prompt.push_str("\n\n[tool unavailable: ");
                        prompt.push_str(&req.tool);
                        prompt.push_str("]\n");
                    }
                }
            }
        }
    }
}

fn build_prompt(ctx: &ConversationContext) -> String {
    let mut p = String::new();
    p.push_str("Intent: ");
    p.push_str(intent_label(ctx.intent));
    p.push_str("\nQuestion: ");
    p.push_str(&ctx.question);
    if !ctx.knowledge.is_empty() {
        p.push_str("\n\nKnowledge:\n");
        for k in &ctx.knowledge {
            p.push_str("- ");
            p.push_str(k);
            p.push('\n');
        }
    }
    p
}

fn intent_label(intent: Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

export!(Node);
